import{_ as d,a0 as r,w as p,s as l,I as s,x as i,a1 as n,A as o,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180702 How to edit Adobe InDesign files with Scribus and Gedit","title":"如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件","tag":"201808","desc":""},"relativePath":"201808/20180702 How to edit Adobe InDesign files with Scribus and Gedit.md","filePath":"[post].md"}'),a={name:"201808/20180702 How to edit Adobe InDesign files with Scribus and Gedit.md"};function g(b,e,m,f,D,I){const t=r("Link");return p(),l("div",null,[e[25]||(e[25]=s("h1",{id:"如何用-scribus-和-gedit-編輯-adobe-indesign-文件",tabindex:"-1"},[i("如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件 "),s("a",{class:"header-anchor",href:"#如何用-scribus-和-gedit-編輯-adobe-indesign-文件","aria-label":"Permalink to “如何用 Scribus 和 Gedit 編輯 Adobe InDesign 文件”"},"​")],-1)),e[26]||(e[26]=s("blockquote",null,[s("p",null,"學習一下這些用開源工具編輯 InDesign 文件的方案。")],-1)),e[27]||(e[27]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/open-indesign-scribus-gedit-graphic.jpg?itok=OPJaGdA5",alt:""})],-1)),e[28]||(e[28]=s("p",null,[i("要想成為一名優秀的平面設計師，您必須善於使用各種各樣專業的工具。現在，對大多數設計師來説，最常用的工具是 "),s("ruby",null,[i("Adobe 全家桶"),s("rt",null,"Adobe Creative Suite")]),i("。")],-1)),s("p",null,[e[2]||(e[2]=i("但是，有時候使用開源工具能夠幫您擺脱困境。比如，您正在使用一台公共打印機打印一份用 Adobe InDesign 創建的文件。這時，您需要對文件做一些簡單的改動（比如，改正一個錯別字），但您無法立刻使用 Adobe 套件。雖然這種情況很少見，但電子雜誌製作軟件 ",-1)),n(t,{href:"https://www.scribus.net/"},{default:o(()=>[...e[0]||(e[0]=[i("Scribus",-1)])]),_:1}),e[3]||(e[3]=i(" 和文本編輯器 ",-1)),n(t,{href:"https://wiki.gnome.org/Apps/Gedit"},{default:o(()=>[...e[1]||(e[1]=[i("Gedit",-1)])]),_:1}),e[4]||(e[4]=i(" 等開源工具可以節約您的時間。",-1))]),s("p",null,[e[7]||(e[7]=i("在本文中，我將向您展示如何使用 Scribus 和 Gedit 編輯 Adobe InDesign 文件。請注意，還有許多其他開源平面設計軟件可以用來代替 Adobe InDesign 或者結合使用。詳情請查看我的文章：",-1)),n(t,{href:"https://opensource.com/life/16/8/open-source-alternatives-graphic-design"},{default:o(()=>[...e[5]||(e[5]=[i("昂貴的工具（從來！）不是平面設計的唯一選擇",-1)])]),_:1}),e[8]||(e[8]=i(" 以及 ",-1)),n(t,{href:"https://opensource.com/article/17/3/scripts-adobe-indesign"},{default:o(()=>[...e[6]||(e[6]=[i("兩個開源 Adobe InDesign 腳本",-1)])]),_:1}),e[9]||(e[9]=i(".",-1))]),e[29]||(e[29]=u('<p>在編寫本文的時候，我閲讀了一些關於如何使用開源軟件編輯 InDesign 文件的Blog，但沒有找到有用的文章。我嘗試了兩個解決方案。一個是：在 InDesign 創建一個 EPS 並在文本編輯器 Scribus 中將其以可編輯文件打開，但這不起作用。另一個是：從 InDesign 中創建一個 IDML（一種舊的 InDesign 文件格式）文件，並在 Scribus 中打開它。第二種方法效果更好，也是我在下文中使用的解決方法。</p><h3 id="編輯名片" tabindex="-1">編輯名片 <a class="header-anchor" href="#編輯名片" aria-label="Permalink to “編輯名片”">​</a></h3><p>我嘗試在 Scribus 中打開和編輯 InDesign 名片文件的效果很好。唯一的問題是字母間的間距有些偏移，以及我用倒過來的 ‘J’ 來創建 “Jeff” 中的 ‘f’ 被翻轉。其他部分，像樣式和顏色等都完好無損。</p><p><img src="https://opensource.com/sites/default/files/uploads/1-business_card_designed_in_adobe_indesign_cc.png" alt="Business card in Adobe InDesign" title="Business card in Adobe InDesign"></p><p><em>圖：在 Adobe InDesign 中編輯名片。</em></p><p><img src="https://opensource.com/sites/default/files/uploads/2-indesign_.idml_file_opened_in_scribus.png" alt="InDesign IDML file opened in Scribus" title="InDesign IDML file opened in Scribus"></p><p><em>圖：在 Scribus 中打開 InDesign IDML 文件。</em></p><h3 id="刪除帶頁碼的書籍中的副本" tabindex="-1">刪除帶頁碼的書籍中的副本 <a class="header-anchor" href="#刪除帶頁碼的書籍中的副本" aria-label="Permalink to “刪除帶頁碼的書籍中的副本”">​</a></h3><p>書籍的轉換並不順利。書籍的正文還 OK，但當我用 Scribus 打開 InDesign 文件，目錄、頁腳和一些首字下沉的段落都出現問題。不過至少，它是一個可編輯的文檔。其中一個問題是一些塊引用中的文字變成了默認的 Arial 字體，這是因為字體樣式（似乎來自其原始的 Word 文檔）的優先級比段落樣式高。這個問題容易解決。</p><p><img src="https://opensource.com/sites/default/files/uploads/3-book_layout_in_indesign.png" alt="Book layout in InDesign" title="Book layout in InDesign"></p><p><em>圖：InDesign 中的書籍佈局。</em></p><p><img src="https://opensource.com/sites/default/files/uploads/4-indesign_.idml_file_of_book_opened_in_scribus.png" alt="InDesign IDML file of book layout opened in Scribus" title="InDesign IDML file of book layout opened in Scribus"></p><p><em>圖：用 Scribus 打開 InDesign IDML 文件的書籍佈局。</em></p><p>當我試圖選擇並刪除一頁文本的時候，發生了奇異事件。我把光標放在文本中，按下 <code>Command + A</code>（“全選”的快捷鍵）。表面看起來高亮顯示了一頁文本，但事實並非如此！</p><p><img src="https://opensource.com/sites/default/files/uploads/5-command-a_in_the_scribus_file.png" alt="Selecting text in Scribus" title="Selecting text in Scribus"></p><p><em>圖：Scribus 中被選中的文本。</em></p><p>當我按下“刪除”鍵，整個文本（不只是高亮的部分）都消失了。</p><p><img src="https://opensource.com/sites/default/files/uploads/6-deleted_text_in_scribus.png" alt="Both pages of text deleted in Scribus" title="Both pages of text deleted in Scribus"></p><p><em>圖：兩頁文本都被刪除了。</em></p><p>然後，更奇異的事情發生了……我按下 <code>Command + Z</code> 鍵來撤回刪除操作，文本恢復，但文本格式全亂套了。</p><p><img src="https://opensource.com/sites/default/files/uploads/7-command-z_in_scribus.png" alt="Undo delete restored the text, but with bad formatting." title="Undo delete restored the text, but with bad formatting."></p><p><em>圖：Command+Z (撤回刪除操作) 恢復了文本，但格式亂套了。</em></p><h3 id="用文本編輯器打開-indesign-文件" tabindex="-1">用文本編輯器打開 InDesign 文件 <a class="header-anchor" href="#用文本編輯器打開-indesign-文件" aria-label="Permalink to “用文本編輯器打開 InDesign 文件”">​</a></h3><p>當您用普通的記事本（比如，Mac 中的 TextEdit）分別打開 Scribus 文件和 InDesign 文件，會發現 Scribus 文件是可讀的，而 InDesign 文件全是亂碼。</p><p>您可以用 TextEdit 對兩者進行更改併成功保存，但得到的文件是損壞的。下圖是當我用 InDesign 打開編輯後的文件時的報錯。</p><p><img src="https://opensource.com/sites/default/files/uploads/8-indesign_error_message.png" alt="InDesign error message" title="InDesign error message"></p><p><em>圖：InDesign 的報錯。</em></p><p>我在 Ubuntu 系統上用文本編輯器 Gedit 編輯 Scribus 時得到了更好的結果。我從命令列啓動了 Gedit，然後打開並編輯 Scribus 文件，保存後，再次使用 Scribus 打開文件時，我在 Gedit 中所做的更改都成功顯示在 Scribus 中。</p><p><img src="https://opensource.com/sites/default/files/uploads/9-scribus_edited_in_gedit_on_linux.png" alt="Editing Scribus file in Gedit" title="Editing Scribus file in Gedit"></p><p><em>圖：用 Gedit 編輯 Scribus 文件。</em></p><p><img src="https://opensource.com/sites/default/files/uploads/10-scribus_opens_after_gedit_changes.png" alt="Result of the Gedit edit in Scribus" title="Result of the Gedit edit in Scribus"></p><p><em>圖：用 Scribus 打開 Gedit 編輯過的文件。</em></p><p>當您正準備打印的時候，客户打來電話説有一個錯別字需要更改，此時您不需要苦等客户爸爸發來新的文件，只需要用 Gedit 打開 Scribus 文件，改正錯別字，繼續打印。</p><h3 id="把圖像拖拽到-id-文件中" tabindex="-1">把圖像拖拽到 ID 文件中 <a class="header-anchor" href="#把圖像拖拽到-id-文件中" aria-label="Permalink to “把圖像拖拽到 ID 文件中”">​</a></h3><p>我將 InDesign 文檔另存為 IDML 文件，這樣我就可以用 Scribus 往其中拖進一些 PDF 文檔。似乎 Scribus 並不能像 InDesign 一樣把 PDF 文檔拖拽進去。於是，我把 PDF 文檔轉換成 JPG 格式的圖片然後導入到 Scribus 中，成功了。但這麼做的結果是，將 IDML 文檔轉換成 PDF 格式後，文件大小非常大。</p><p><img src="https://opensource.com/sites/default/files/uploads/11-large_pdf_size.png" alt="Huge PDF file" title="Huge PDF file"></p><p><em>圖：把 Scribus 轉換成 PDF 時得到一個非常大的文件</em>。</p><p>我不確定為什麼會這樣——這個坑留着以後再填吧。</p><p>您是否有使用開源軟件編輯平面圖形文件的技巧？如果有，請在評論中分享哦。</p><hr>',40)),s("p",null,[e[11]||(e[11]=i("via: ",-1)),n(t,{href:"https://opensource.com/article/18/7/adobe-indesign-open-source-tools"},{default:o(()=>[...e[10]||(e[10]=[i("https://opensource.com/article/18/7/adobe-indesign-open-source-tools",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=i("作者：",-1)),n(t,{href:"https://opensource.com/users/rikki-endsley"},{default:o(()=>[...e[12]||(e[12]=[i("Jeff Macharyas",-1)])]),_:1}),e[17]||(e[17]=i(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[13]||(e[13]=[i("lujun9972",-1)])]),_:1}),e[18]||(e[18]=i(" 譯者：",-1)),n(t,{href:"https://github.com/XiatianSummer"},{default:o(()=>[...e[14]||(e[14]=[i("XiatianSummer",-1)])]),_:1}),e[19]||(e[19]=i(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[15]||(e[15]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[22]||(e[22]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[20]||(e[20]=[i("LCTT",-1)])]),_:1}),e[23]||(e[23]=i(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:o(()=>[...e[21]||(e[21]=[i("Linux中國",-1)])]),_:1}),e[24]||(e[24]=i(" 榮譽推出",-1))])])}const A=d(a,[["render",g]]);export{_ as __pageData,A as default};
